import { expect, it } from "vitest";
import { Raw, startBroker } from "./helpers.js";

it("a subscriber that keeps up is NOT dropped", async () => {
  const { broker, port } = await startBroker({ maxPending: 64 * 1024 });
  const sub = await Raw.ready(port);
  const pub = await Raw.ready(port);
  try {
    sub.send("SUB s 1\r\n");
    await sub.sync();
    const body = "y".repeat(1024);
    for (let round = 0; round < 10; round++) {
      for (let i = 0; i < 50; i++) pub.send(`PUB s ${body.length}\r\n${body}\r\n`);
      await pub.sync();   // server has routed this round
      await sub.sync();   // subscriber has read it
    }
    expect(sub.received.match(/MSG s 1 1024\r\n/g)).toHaveLength(500);
    expect(broker.stats().slowConsumers).toBe(0);
  } finally {
    sub.close();
    pub.close();
    await broker.close(500);
  }
});
